import datetime, hashlib, json, pathlib, sys
out = pathlib.Path.home() / 'Documents' / 'Obsidian Vault' / 'graphify-out'
marker, graph = out / 'refresh.json', out / 'graph.json'
if not marker.exists():
    print('no refresh marker - the graph has not been refreshed', file=sys.stderr); sys.exit(1)
try:
    rec = json.loads(marker.read_text())
except Exception as exc:
    print(f'refresh marker unreadable: {exc}', file=sys.stderr); sys.exit(1)
if not graph.exists():
    print('graph.json is missing', file=sys.stderr); sys.exit(1)
raw = graph.read_bytes()
want = rec.get('graph_sha256')
if not want or hashlib.sha256(raw).hexdigest() != want:
    print('graph.json is not the artifact the last refresh produced (stale or replaced)', file=sys.stderr); sys.exit(1)
data = json.loads(raw)
if not data.get('nodes'):
    print('graph.json contains no nodes', file=sys.stderr); sys.exit(1)
try:
    stamp = datetime.datetime.fromisoformat(rec['refreshed_at'])
except Exception:
    print('refresh marker has no usable refreshed_at', file=sys.stderr); sys.exit(1)
wib = datetime.timezone(datetime.timedelta(hours=7))
today = datetime.datetime.now(wib).strftime('%Y-%m-%d')
if stamp.astimezone(wib).strftime('%Y-%m-%d') != today:
    print(f"last refresh {rec['refreshed_at']} is not today ({today} WIB) - graph is stale", file=sys.stderr); sys.exit(1)
print(f"graph refreshed {rec['refreshed_at']} - {len(data['nodes'])} nodes - hash matches")
